(() => {
  'use strict';

  class SyncAdapter {
    async push(){throw new Error('SyncAdapter.push must be implemented');}
    async pull(){throw new Error('SyncAdapter.pull must be implemented');}
    status(){return{state:'saved-here'};}
  }

  class LocalOnlySyncAdapter extends SyncAdapter {
    async push(){return{acknowledged:[]};}
    async pull(){return{operations:[]};}
    status(){return{state:'saved-here'};}
  }

  class SupabaseSyncAdapter extends SyncAdapter {
    constructor({cloudService,onStatus=()=>{}}){super();this.cloudService=cloudService;this.onStatus=onStatus;this.current='saved-here';this.pending=null;}
    setStatus(state){if(this.current===state)return;this.current=state;this.onStatus({state});}
    status(){return{state:this.current};}
    available(){return navigator.onLine&&this.cloudService.isConfigured()&&Boolean(this.cloudService.user());}
    async push(context){return this.sync(context);}
    async pull(context){return this.sync(context);}
    async sync(context){
      if(this.pending){try{await this.pending;}catch(_error){}return this.sync(context);}
      if(!this.available()){this.setStatus('saved-here');return{songs:null,ideas:null};}
      const hasLocal=(context.state.songs?.length||context.state.ideas?.length)&&!context.state.cloudBackupAt;
      if(hasLocal){this.setStatus('saved-here');return{songs:null,ideas:null,confirmationRequired:true};}
      this.setStatus('syncing');this.pending=this.cloudService.syncDocuments(context.state,context.repository,context.songDocuments)
        .then(result=>{this.setStatus('backed-up');return result;})
        .catch(error=>{this.setStatus('saved-here');const song=context.state.songs?.find(item=>item.id===context.state.selectedSongId);context.repository.enqueueMetric('sync_failure',{songId:song?.id||null}).catch(()=>{});throw error;})
        .finally(()=>{this.pending=null;});
      return this.pending;
    }
  }

  window.CoWriterSync={SyncAdapter,LocalOnlySyncAdapter,SupabaseSyncAdapter};
})();
