import * as Y from 'yjs';
import {IndexeddbPersistence} from 'y-indexeddb';

const LOCAL_ORIGIN=Symbol('cowriter-local');
const BOOTSTRAP_ORIGIN=Symbol('cowriter-bootstrap');
const REMOTE_ORIGIN=Symbol('cowriter-remote');
const DEVICE_KEYS=new Set(['lastView','viewMemory','shapeView','activeProfileId','chartLayout','cloudMembership']);
const TEXT_KEYS=new Set(['title','brainDump','text','label','name','note','tuningNote','progression','role','ipi','pro']);
const TYPE_KEY='__cowriterType';
const INTERNAL_KEYS=new Set([TYPE_KEY,'anchorRelative']);
const ENTITY_ARRAY='entity-array';

const clone=value=>value==null?value:structuredClone(value);
const base64FromBytes=bytes=>{let value='';for(let offset=0;offset<bytes.length;offset+=0x8000)value+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));return btoa(value);};
const bytesFromBase64=value=>Uint8Array.from(atob(value),character=>character.charCodeAt(0));

function persistentSong(song){
  const result=clone(song)||{};DEVICE_KEYS.forEach(key=>delete result[key]);return result;
}

function textPatch(previous,next){
  const value=String(next??'');if(previous===value)return null;
  let prefix=0;while(prefix<previous.length&&prefix<value.length&&previous[prefix]===value[prefix])prefix+=1;
  let suffix=0;while(suffix<previous.length-prefix&&suffix<value.length-prefix&&previous[previous.length-1-suffix]===value[value.length-1-suffix])suffix+=1;
  return{index:prefix,remove:previous.length-prefix-suffix,insert:value.slice(prefix,value.length-suffix)};
}
function applyTextPatch(text,patch){if(!patch)return;if(patch.remove)text.delete(patch.index,patch.remove);if(patch.insert)text.insert(patch.index,patch.insert);}
function patchText(text,next){
  applyTextPatch(text,textPatch(text.toString(),next));
}

function ensureMap(parent,key){const current=parent.get(key);if(current instanceof Y.Map)return current;const value=new Y.Map();parent.set(key,value);return value;}
function ensureArray(parent,key){const current=parent.get(key);if(current instanceof Y.Array)return current;const value=new Y.Array();parent.set(key,value);return value;}
function ensureText(parent,key){const current=parent.get(key);if(current instanceof Y.Text)return current;const value=new Y.Text();parent.set(key,value);return value;}

function reconcileArray(parent,key,value,path){
  const entities=value.length>0&&value.every(item=>item&&typeof item==='object'&&!Array.isArray(item)&&item.id!=null);
  if(!entities){const array=ensureArray(parent,key),current=array.toJSON();if(JSON.stringify(current)!==JSON.stringify(value)){if(array.length)array.delete(0,array.length);if(value.length)array.insert(0,clone(value));}return;}
  const collection=ensureMap(parent,key);collection.set(TYPE_KEY,ENTITY_ARRAY);const order=ensureArray(collection,'order'),items=ensureMap(collection,'items'),ids=value.map(item=>String(item.id)),existing=order.toArray();
  if(existing.length!==ids.length||existing.some((id,index)=>id!==ids[index])){if(order.length)order.delete(0,order.length);if(ids.length)order.insert(0,ids);}
  const wanted=new Set(ids);for(const item of value){const id=String(item.id),map=ensureMap(items,id);reconcileObject(map,item,`${path}.${id}`);}
  for(const id of Array.from(items.keys()))if(!wanted.has(id))items.delete(id);
}

function reconcileValue(parent,key,value,path){
  if(Array.isArray(value)){reconcileArray(parent,key,value,path);return;}
  if(value&&typeof value==='object'){const map=ensureMap(parent,key);reconcileObject(map,value,path);return;}
  if(typeof value==='string'&&TEXT_KEYS.has(key)){patchText(ensureText(parent,key),value);return;}
  const target=value??null;if(parent.get(key)!==target)parent.set(key,target);
}

function reconcileObject(map,value,path='song'){
  const wanted=new Set(Object.keys(value));for(const key of Array.from(map.keys()))if(!INTERNAL_KEYS.has(key)&&!wanted.has(key))map.delete(key);
  for(const [key,item] of Object.entries(value))reconcileValue(map,key,item,`${path}.${key}`);
}

function entityItems(parent,key){const collection=parent?.get?.(key),items=collection instanceof Y.Map?collection.get('items'):null;return items instanceof Y.Map?items:null;}
function entityById(parent,key,id){return entityItems(parent,key)?.get(String(id))||null;}
function textForTarget(root,target={}){
  if(target.kind==='song-title')return root.get('title');
  if(target.kind==='plan')return root.get('plan')?.get?.('brainDump');
  if(target.kind==='saved-progression')return root.get('workbench')?.get?.('progression');
  if(target.kind==='shape-block')return entityById(root,'shapeBlocks',target.blockId)?.get?.('text');
  const section=target.sectionId?entityById(root,'sections',target.sectionId):null;
  if(target.kind==='section-label')return section?.get?.('label');
  if(target.kind==='line-text')return entityById(section,'lines',target.lineId)?.get?.('text');
  return null;
}
function syncChordRelativePositions(root,doc){
  const sections=entityItems(root,'sections');if(!sections)return;
  for(const section of sections.values()){
    const lines=entityItems(section,'lines');if(!lines)continue;
    for(const line of lines.values()){
      const text=line.get('text'),chords=entityItems(line,'chords');if(!(text instanceof Y.Text)||!chords)continue;
      for(const chord of chords.values()){
        const anchor=Math.max(0,Math.min(text.length,Number(chord.get('anchor'))||0)),encoded=chord.get('anchorRelative');let current=null;
        if(encoded){try{const absolute=Y.createAbsolutePositionFromRelativePosition(Y.decodeRelativePosition(Uint8Array.from(encoded)),doc);if(absolute?.type===text)current=absolute.index;}catch(_error){}}
        if(current!==anchor)chord.set('anchorRelative',Array.from(Y.encodeRelativePosition(Y.createRelativePositionFromTypeIndex(text,anchor))));
      }
    }
  }
}

function resolveChordRelativePositions(root,doc,value){
  const sections=entityItems(root,'sections'),plainSections=new Map((value.sections||[]).map(section=>[String(section.id),section]));if(!sections)return value;
  for(const [sectionId,section] of sections.entries()){
    const plainSection=plainSections.get(String(sectionId)),lines=entityItems(section,'lines'),plainLines=new Map((plainSection?.lines||[]).map(line=>[String(line.id),line]));if(!lines)continue;
    for(const [lineId,line] of lines.entries()){
      const plainLine=plainLines.get(String(lineId)),text=line.get('text'),chords=entityItems(line,'chords'),plainChords=new Map((plainLine?.chords||[]).map(chord=>[String(chord.id),chord]));if(!(text instanceof Y.Text)||!chords)continue;
      for(const [chordId,chord] of chords.entries()){
        const plainChord=plainChords.get(String(chordId)),encoded=chord.get('anchorRelative');if(!plainChord||!encoded)continue;
        try{const absolute=Y.createAbsolutePositionFromRelativePosition(Y.decodeRelativePosition(Uint8Array.from(encoded)),doc);if(absolute?.type===text)plainChord.anchor=absolute.index;}catch(_error){}
        delete plainChord.anchorRelative;
      }
    }
  }
  return value;
}

function fromShared(value){
  if(value instanceof Y.Text)return value.toString();
  if(value instanceof Y.Array)return value.toArray().map(fromShared);
  if(value instanceof Y.Map){
    if(value.get(TYPE_KEY)===ENTITY_ARRAY){const order=value.get('order'),items=value.get('items');return (order instanceof Y.Array&&items instanceof Y.Map)?order.toArray().map(id=>fromShared(items.get(String(id)))).filter(Boolean):[];}
    const result={};for(const [key,item] of value.entries())if(key!==TYPE_KEY)result[key]=fromShared(item);return result;
  }
  return clone(value);
}

class SongDocument {
  constructor(songId,repository,channel){this.songId=songId;this.repository=repository;this.doc=new Y.Doc({guid:songId});this.root=this.doc.getMap('song');this.persistence=new IndexeddbPersistence(`cowriter-song-v1-${channel}-${songId}`,this.doc);this.writeChain=Promise.resolve();this.listeners=new Set();this.undoManager=new Y.UndoManager(this.root,{trackedOrigins:new Set([LOCAL_ORIGIN]),captureTimeout:750});this.ready=new Promise(resolve=>this.persistence.once('synced',resolve));this.doc.on('update',(update,origin)=>{if(origin!==LOCAL_ORIGIN&&origin!==this.undoManager)return;const updateBase64=base64FromBytes(update);this.writeChain=this.writeChain.then(()=>this.repository.enqueueOperation({id:`yupdate_${this.repository.clientIdentifier()}_${songId}_${crypto.randomUUID()}`,entityType:'song-document',entityId:songId,songId,kind:'yjs-update',payload:{updateBase64}}));this.listeners.forEach(listener=>listener(updateBase64));});}
  async initialise(song){await this.ready;if(this.root.size===0)this.doc.transact(()=>{reconcileObject(this.root,persistentSong(song));syncChordRelativePositions(this.root,this.doc);},BOOTSTRAP_ORIGIN);return this.read(song);}
  async write(song){await this.ready;this.undoManager.stopCapturing();this.doc.transact(()=>{reconcileObject(this.root,persistentSong(song));syncChordRelativePositions(this.root,this.doc);},LOCAL_ORIGIN);this.undoManager.stopCapturing();await this.writeChain;}
  async bindText(target,listener=()=>{}){
    await this.ready;const text=textForTarget(this.root,target);if(!(text instanceof Y.Text))throw new Error(`Shared text target is unavailable: ${target?.kind||'unknown'}`);
    let anchor=null,head=null;
    const selection=()=>{
      if(!anchor||!head)return null;
      const start=Y.createAbsolutePositionFromRelativePosition(anchor,this.doc),end=Y.createAbsolutePositionFromRelativePosition(head,this.doc);
      if(start?.type!==text||end?.type!==text)return null;
      return{start:start.index,end:end.index};
    };
    const observer=event=>listener({value:text.toString(),delta:event.delta,origin:event.transaction.origin,remote:event.transaction.origin===REMOTE_ORIGIN,selection:selection()});
    text.observe(observer);
    return{
      value:()=>text.toString(),
      replace:async value=>{this.doc.transact(()=>{patchText(text,value);this.root.set('updatedAt',new Date().toISOString());syncChordRelativePositions(this.root,this.doc);},LOCAL_ORIGIN);await this.writeChain;return this.read();},
      edit:async(previous,value)=>{const patch=textPatch(String(previous??''),value);this.doc.transact(()=>{applyTextPatch(text,patch);this.root.set('updatedAt',new Date().toISOString());syncChordRelativePositions(this.root,this.doc);},LOCAL_ORIGIN);await this.writeChain;return this.read();},
      captureSelection:(start,end=start)=>{anchor=Y.createRelativePositionFromTypeIndex(text,Math.max(0,Math.min(text.length,Number(start)||0)));head=Y.createRelativePositionFromTypeIndex(text,Math.max(0,Math.min(text.length,Number(end)||0)));},
      selection,
      finishCapture:()=>this.undoManager.stopCapturing(),
      flush:async()=>{await this.writeChain;return this.read();},
      destroy:()=>text.unobserve(observer)
    };
  }
  read(deviceSong={}){const value=resolveChordRelativePositions(this.root,this.doc,fromShared(this.root));DEVICE_KEYS.forEach(key=>{if(deviceSong[key]!==undefined)value[key]=clone(deviceSong[key]);});return value;}
  apply(updateBase64){Y.applyUpdate(this.doc,bytesFromBase64(updateBase64),REMOTE_ORIGIN);}
  fullUpdate(){return base64FromBytes(Y.encodeStateAsUpdate(this.doc));}
  subscribe(listener){this.listeners.add(listener);return()=>this.listeners.delete(listener);}
  async undo(deviceSong={}){if(!this.undoManager.canUndo())return null;this.undoManager.undo();await this.writeChain;return this.read(deviceSong);}
  async redo(deviceSong={}){if(!this.undoManager.canRedo())return null;this.undoManager.redo();await this.writeChain;return this.read(deviceSong);}
  canUndo(){return this.undoManager.canUndo();}
  canRedo(){return this.undoManager.canRedo();}
  async destroy(){await this.writeChain;this.persistence.destroy();this.doc.destroy();}
}

class SongDocumentManager {
  constructor({repository,channel='stable'}){this.repository=repository;this.channel=channel;this.documents=new Map();}
  document(songId){let value=this.documents.get(songId);if(!value){value=new SongDocument(songId,this.repository,this.channel);this.documents.set(songId,value);}return value;}
  async initialise(songs){const result=[];for(const song of songs||[])result.push(await this.document(song.id).initialise(song));return result;}
  async writeAll(songs){for(const song of songs||[])await this.document(song.id).write(song);}
  async hydrate(songId,updates,fallback){const document=this.document(songId);await document.ready;for(const update of updates||[])document.apply(update);if(document.root.size===0)return document.initialise(fallback);return document.read(fallback);}
  async apply(songId,updateBase64,deviceSong){const document=this.document(songId);await document.ready;document.apply(updateBase64);return document.read(deviceSong);}
  async ensure(song){return this.document(song.id).initialise(song);}
  async read(songId,deviceSong){const document=this.document(songId);await document.ready;return document.read(deviceSong);}
  async bindText(songId,target,listener){return this.document(songId).bindText(target,listener);}
  subscribe(songId,listener){return this.document(songId).subscribe(listener);}
  async undo(songId,deviceSong){const document=this.document(songId);await document.ready;return document.undo(deviceSong);}
  async redo(songId,deviceSong){const document=this.document(songId);await document.ready;return document.redo(deviceSong);}
  canUndo(songId){return this.document(songId).canUndo();}
  canRedo(songId){return this.document(songId).canRedo();}
  fullUpdate(songId){return this.document(songId).fullUpdate();}
  async destroy(){await Promise.all(Array.from(this.documents.values(),document=>document.destroy()));this.documents.clear();}
}

window.CoWriterSongDocument={SongDocumentManager,create:options=>new SongDocumentManager(options),persistentSong,base64FromBytes,bytesFromBase64};
