(() => {
  'use strict';

  const CLIENT_VERSION='0.6.3';
  const PROTOCOL_VERSION=1;

  class RealtimeCollaboration {
    constructor({cloudService,songDocuments,clientId,onRemote=()=>{},onPresence=()=>{},onIncompatible=()=>{},onStatus=()=>{}}){
      this.cloudService=cloudService;this.songDocuments=songDocuments;this.clientId=clientId;this.onRemote=onRemote;this.onPresence=onPresence;this.onIncompatible=onIncompatible;this.onStatus=onStatus;this.channel=null;this.songId=null;this.context={};this.unsubscribeDocument=null;this.status='closed';this.pendingBroadcasts=new Map();this.receivedUpdates=0;this.sentUpdates=0;this.lastError=null;
    }
    available(){return navigator.onLine&&this.cloudService.isConfigured()&&Boolean(this.cloudService.user());}
    async open(song,context={}){
      if(!song||song.cloudMembership?.role==='revoked'||!this.available()){await this.close();return;}
      if(this.songId===song.id&&this.channel){this.setContext(context);return;}
      await this.close();this.songId=song.id;this.context=context;this.status='connecting';this.onStatus(this.status);
      const user=this.cloudService.user(),channel=this.cloudService.realtimeChannel(`song:${song.id}`,user.id);this.channel=channel;
      channel.on('broadcast',{event:'yjs-update'},async({payload})=>{
        if(!payload||payload.sender===this.clientId||payload.songId!==this.songId)return;
        if(Number(payload.protocol||0)>PROTOCOL_VERSION){this.onIncompatible(payload.clientVersion||'a newer version');return;}
        const localSong=this.context.song?.();if(!localSong)return;
        try{const next=await this.songDocuments.apply(this.songId,payload.updateBase64,localSong);this.receivedUpdates+=1;this.lastError=null;this.onRemote(next,payload);this.channel?.send({type:'broadcast',event:'yjs-ack',payload:{songId:this.songId,target:payload.sender,updateId:payload.updateId,sender:this.clientId}}).catch(()=>{});}
        catch(error){this.lastError=error?.message||String(error);console.warn('Live update could not be applied',error);}
      });
      channel.on('broadcast',{event:'yjs-ack'},({payload})=>{if(payload?.target!==this.clientId||payload.songId!==this.songId)return;const pending=this.pendingBroadcasts.get(payload.updateId);if(pending)clearTimeout(pending.timer);this.pendingBroadcasts.delete(payload.updateId);});
      channel.on('broadcast',{event:'asset-metadata'},({payload})=>{if(payload?.songId===this.songId)this.onRemote(null,payload);});
      channel.on('presence',{event:'sync'},()=>this.publishPresence());
      channel.on('presence',{event:'join'},()=>this.publishPresence());
      this.unsubscribeDocument=this.songDocuments.subscribe(song.id,updateBase64=>{
        if(!this.channel||!this.available())return;
        const payload={songId:this.songId,updateId:crypto.randomUUID(),updateBase64,sender:this.clientId,protocol:PROTOCOL_VERSION,clientVersion:CLIENT_VERSION};this.queueUpdate(payload);
      });
      channel.subscribe(async status=>{
        if(channel!==this.channel)return;
        if(status==='SUBSCRIBED'){this.status='live';await channel.track(this.presencePayload());}
        else if(['CHANNEL_ERROR','TIMED_OUT'].includes(status))this.status='retrying';
        else if(status==='CLOSED')this.status='closed';
        this.onStatus(this.status);
      });
    }
    queueUpdate(payload){const record={payload,attempts:0,timer:null};this.pendingBroadcasts.set(payload.updateId,record);this.transmitUpdate(record);}
    hasRemotePeers(){const ownUser=this.cloudService.user()?.id;return Object.values(this.channel?.presenceState()||{}).flat().some(person=>person.clientId!==this.clientId&&person.userId!==ownUser);}
    transmitUpdate(record){if(!this.pendingBroadcasts.has(record.payload.updateId)||!this.channel||!this.available())return;record.attempts+=1;const expectAck=this.hasRemotePeers();if(expectAck)record.timer=setTimeout(()=>{if(record.attempts<4)this.transmitUpdate(record);else{this.pendingBroadcasts.delete(record.payload.updateId);this.lastError='Live update acknowledgement timed out';this.onStatus('retrying');}},350*record.attempts);this.channel.send({type:'broadcast',event:'yjs-update',payload:record.payload}).then(result=>{if(result==='ok'){this.sentUpdates+=1;if(!expectAck)this.pendingBroadcasts.delete(record.payload.updateId);return;}this.lastError=`Realtime broadcast ${result||'failed'}`;if(!expectAck)this.pendingBroadcasts.delete(record.payload.updateId);}).catch(error=>{this.lastError=error?.message||String(error);if(!expectAck)this.pendingBroadcasts.delete(record.payload.updateId);});}
    presencePayload(){const user=this.cloudService.user(),context=this.context;return{userId:user?.id,email:user?.email||'',clientId:this.clientId,clientVersion:CLIENT_VERSION,protocol:PROTOCOL_VERSION,activeView:context.view?.()||'write',activeSectionId:context.section?.()||null,activeLineId:context.line?.()||null,shapeSelection:context.shapeSelection?.()||[],onlineAt:new Date().toISOString()};}
    async setContext(context={}){this.context={...this.context,...context};if(this.channel&&this.status==='live')try{await this.channel.track(this.presencePayload());}catch(_error){}}
    publishPresence(){if(!this.channel)return;const ownUser=this.cloudService.user()?.id,people=Object.values(this.channel.presenceState()||{}).flat().filter(person=>person.clientId!==this.clientId&&person.userId!==ownUser);for(const person of people)if(Number(person.protocol||0)>PROTOCOL_VERSION)this.onIncompatible(person.clientVersion||'a newer version');this.onPresence(people);}
    async broadcastAsset(metadata){if(!this.channel||this.status!=='live'||metadata?.songId!==this.songId)return;await this.channel.send({type:'broadcast',event:'asset-metadata',payload:{songId:this.songId,sender:this.clientId,metadata}});}
    debug(){return{songId:this.songId,status:this.status,receivedUpdates:this.receivedUpdates,sentUpdates:this.sentUpdates,lastError:this.lastError};}
    async close(){this.unsubscribeDocument?.();this.unsubscribeDocument=null;for(const pending of this.pendingBroadcasts.values())clearTimeout(pending.timer);this.pendingBroadcasts.clear();const channel=this.channel;this.channel=null;this.songId=null;this.status='closed';this.onPresence([]);this.onStatus(this.status);if(channel)await this.cloudService.removeRealtimeChannel(channel);}
  }

  window.CoWriterRealtime={create:options=>new RealtimeCollaboration(options),RealtimeCollaboration,CLIENT_VERSION,PROTOCOL_VERSION};
})();
